app.post('/payments', async (req, res) => {
  const key = req.header('Idempotency-Key');
  const hit = await redis.get(`idem:${key}`);
  if (hit) return res.status(200).json(JSON.parse(hit));
  const result = await psp.charge(req.body);
  await redis.set(`idem:${key}`, JSON.stringify(result), 'EX', 86400);
  res.status(201).json(result);
});

export async function importContacts(rows, repo) {
  let imported = 0;
  rows.forEach(async (row) => {
    try { await repo.save(row); imported++; }
    catch (e) { logger.error(e); }
  });
  return { imported };
}

